input.new_string:
  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  assertNotArchived("Organization", input.orgId, org);

  const archived = await orgRepo.archiveOrg(input.orgId);

  await emit("organization.deleted", {
    ...envelope(archived.id, actor.userId),
    slug: archived.slug,
  });

  await record(archived.id, "organization.deleted", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: archived.id,
    projectId: null,
    summary: `${archived.name} deleted`,
  });

  return archived;
}

/**
 * Brings a deleted workspace back. No `Actor` can be resolved while it is
 * deleted, so the caller is identified by user id and checked against the
 * membership row that deletion left in place.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  const member = await memberRepo.findMember(orgId, userId);
  if (!member) throw new NotFoundError("Organization", orgId);

  if (org.archivedAt !== null && retentionClosed(org.archivedAt)) {
    throw new NotFoundError("Organization", orgId);
  }

  assertCan(
    { userId, orgId, role: member.role },
    "org:restore",
    orgResource(orgId),
  );

  if (org.archivedAt === null) return org;

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(restored.id, userId),
    slug: restored.slug,
  });

  await record(restored.id, "organization.restored", {
    actorId: userId,
    subjectKind: "organization",
    subjectId: restored.id,
    projectId: null,
    summary: `${restored.name} restored`,
  });

  return restored;
}

/** True once the grace window that starts at `archivedAt` has closed. */
function retentionClosed(archivedAt: string): boolean {
  const cutoff = new Date(
    Date.now() - DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY,
  ).toISOString();
  return archivedAt <= cutoff;
}

