  return toOrganization(row);
}

/** Deleted workspaces whose grace window has closed at `cutoff`. */
export async function listOrgsArchivedBefore(
  cutoff: IsoTimestamp,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select()
    .from(organizations)
    .where(
      and(
        isNotNull(organizations.archivedAt),
        lte(organizations.archivedAt, cutoff),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row));
}

/**
 * Removes the workspace row and every row that belongs to it. User accounts
 * stay; sessions that pointed at the workspace lose their active workspace.
 */
export async function purgeOrganization(orgId: OrgId): Promise<void> {
  const db = getDb();
  const stamp = toIsoTimestamp(new Date());

  db.delete(issueLabels).where(eq(issueLabels.orgId, orgId)).run();
  db.delete(attachments).where(eq(attachments.orgId, orgId)).run();
  db.delete(comments).where(eq(comments.orgId, orgId)).run();
  db.delete(issues).where(eq(issues.orgId, orgId)).run();
  db.delete(labels).where(eq(labels.orgId, orgId)).run();
  db.delete(projectMembers).where(eq(projectMembers.orgId, orgId)).run();
  db.delete(projects).where(eq(projects.orgId, orgId)).run();
  db.delete(invitations).where(eq(invitations.orgId, orgId)).run();
  db.delete(members).where(eq(members.orgId, orgId)).run();
  db.delete(notifications).where(eq(notifications.orgId, orgId)).run();
  db.delete(notificationPreferences)
    .where(eq(notificationPreferences.orgId, orgId))
    .run();
  db.delete(activityEvents).where(eq(activityEvents.orgId, orgId)).run();
  db.delete(invoices).where(eq(invoices.orgId, orgId)).run();
  db.delete(subscriptions).where(eq(subscriptions.orgId, orgId)).run();
  db.delete(webhookDeliveries).where(eq(webhookDeliveries.orgId, orgId)).run();
  db.delete(webhookEndpoints).where(eq(webhookEndpoints.orgId, orgId)).run();
  db.delete(searchIndex).where(eq(searchIndex.orgId, orgId)).run();
  db.delete(rateLimitBuckets).where(eq(rateLimitBuckets.orgId, orgId)).run();
  db.delete(organizationUsage).where(eq(organizationUsage.orgId, orgId)).run();

  db.update(sessions)
    .set({ activeOrgId: null, updatedAt: stamp })
    .where(eq(sessions.activeOrgId, orgId))
    .run();

  db.delete(organizations).where(eq(organizations.id, orgId)).run();
}

